    "phase_1_crosscoder_training": {
      "title": "Three-Model Crosscoder Training (Weeks 1-4)",
      "architecture": "Adopt the three-model sparse crosscoder from Shi et al. (2604.25011). The encoder uses model-specific weights with a shared bias: f(x_j) = ReLU(sum_{i in {A,B,C}} W_enc^(i) * a^(i)(x_j) + b_enc), where a^(i)(x_j) is the residual-stream activation at position j from model i. The decoder is shared across models with model-specific output: a_hat^(i)(x_j) = sum_k f_k(x_j) * W_dec,k^(i). This produces a single shared sparse feature space where each feature has a continuous attribution to each model.",
      "enhancement_over_2604_25011": "We replace standard TopK activation (used in Shi et al.) with BatchTopK from the Delta-Crosscoder framework, which dynamically adjusts sparsity across the batch and is strictly superior to fixed TopK in reconstruction quality per unit sparsity. This is a direct methodological improvement over 2604.25011.",
      "feature_attribution": "Model Attribution Score (MAS): MAS_i(k) = ||W_dec,k^(i)||_1 / sum_j ||W_dec,k^(j)||_1, yielding a continuous [0,1] score per model per feature. Features with MAS_B > 0.6 are discriminative-dominant; MAS_C > 0.6 are generative-dominant; max(MAS) < 0.5 are shared. This replaces the binary Dual-K classification, providing finer-grained attribution without arbitrary thresholds.",
      "layers": "Five representative layers of the 32-layer Qwen2.5-Math-7B architecture: layers 4 (early/syntactic), 10 (mid-early), 16 (middle/transitional), 22 (mid-late/semantic), 28 (late/decision). This extends Shi et al.'s single-layer design to capture the depth-dependent structure of verification features.",
      "feature_dictionary_size": "32,768 features per crosscoder (matching Shi et al.), yielding 5 crosscoders x 32K features = 163,840 total features before filtering.",
      "training_data": "Residual-stream activations collected from all three models processing identical mathematical reasoning traces from the MATH and GSM8K training sets, including both correct and erroneous solution steps. Approximately 500K token positions per layer.",
      "training_procedure": "Adam optimizer, learning rate 3e-4 with cosine decay, batch size 4096 tokens, 50K steps per crosscoder. L1 sparsity coefficient tuned to achieve ~95% dead feature rate (standard for interpretability-grade dictionaries). Each crosscoder trains in approximately 30 hours on 1x A100-80GB.",
      "compute": "5 crosscoders x 30h = 150 GPU-hours"
    },
    "phase_2_feature_taxonomy_and_falsification": {
      "title": "Feature Taxonomy Construction and Falsification Validation (Weeks 4-7)",
      "step_2a_automated_feature_labeling": "Apply automated interpretability (max-activating examples, activation patching) to label the top-500 most active features per crosscoder. Classify features into: (i) error-pattern features -- those that activate on common mathematical mistakes (arithmetic errors, sign errors, off-by-one errors, unit conversion errors) detectable by pattern matching without deep reasoning; (ii) error-explanation features -- those that activate on multi-step logical chain verification, constraint propagation, or proof-structure validation requiring extended reasoning; (iii) fluency features -- those that activate on surface-level formatting, notation, or presentation quality; (iv) shared mathematical features -- those with low MAS variance that encode general mathematical knowledge present in all three models.",
      "step_2b_hypothesis_testing": {
        "H1a": {
          "prediction": "Discriminative PRM training (Arm B) develops error-pattern features (high MAS_B, activating on common mistake types) but under-develops error-explanation features compared to generative PRM (Arm C).",
          "metric": "Count features classified as error-pattern with MAS_B > 0.6 vs. features classified as error-explanation with MAS_B > 0.6. Compare ratio to Arm C.",
          "expected_outcome": "Discriminative PRM has >= 2x more error-pattern features than error-explanation features; generative PRM has roughly balanced or error-explanation-dominant distribution."
        },
        "H1b": {
          "prediction": "Generative PRM training develops error-explanation features that are paradigm-exclusive (MAS_C > 0.7), representing novel verification capabilities not present in the base model or discriminative PRM.",
          "metric": "Count features classified as error-explanation with MAS_C > 0.7. These should constitute at least 15% of all generative-dominant features.",
          "expected_outcome": "A substantial cluster of generative-exclusive error-explanation features exists, concentrated in layers 16-28."
        },
        "H1c": {
          "prediction": "The base model (Arm A) already encodes substantial error-detection capability via shared features (max MAS < 0.5), explaining why RL induces PRM capabilities without explicit verification training.",
          "metric": "Fraction of error-pattern features that are shared (max MAS < 0.5) vs. paradigm-exclusive.",
          "expected_outcome": "At least 40% of error-pattern features are shared across all three models, with the base model contributing meaningfully to their activation."
        },
        "H2_falsification_rates": {
          "prediction": "Behavioral falsification on PRM-Bench and ProcessBench will confirm the feature taxonomy: features labeled as error-explanation should predict performance on multi-step verification tasks better than error-pattern features.",
          "metric": "Correlation between per-problem feature activation profiles and PRM-Bench/ProcessBench accuracy, stratified by feature class.",
          "falsification_criterion": "If error-pattern features predict multi-step verification accuracy equally well as error-explanation features (correlation difference < 0.05), the taxonomy distinction is not behaviorally meaningful."
        }
      },
      "step_2c_falsification_protocol": {
        "falsification_of_H1": "If discriminative PRMs show equally rich error-explanation features (comparable count and MAS values to generative PRM), then the performance gap is inference-architecture-driven (the discriminative model HAS the features but cannot leverage them in its classification head), not representational. This would be a significant finding redirecting the field toward inference-time interventions rather than training paradigm changes.",
        "falsification_of_CoT_value": "If generative PRMs show primarily fluency features (majority of MAS_C > 0.6 features classified as fluency rather than error-explanation), then CoT verification is surface mimicry -- the model learns to produce verification-like text without developing genuine multi-step reasoning features. This would challenge the ThinkPRM premise.",
        "validation_method": "Behavioral validation on PRM-Bench (comprehensive PRM evaluation) and ProcessBench (step-level evaluation). Features identified as causally relevant via activation patching should correlate with per-problem accuracy (Pearson r > 0.3 to be considered meaningful)."
      },
      "compute": "Feature analysis and falsification validation: ~200 GPU-hours (activation collection, patching experiments, benchmark evaluation)"
    },
    "phase_3_exploratory_steering": {
      "title": "Exploratory Feature Steering (Weeks 7-9)",
      "rationale": "Shi et al. (2604.25011) demonstrate that crosscoder features can be zeroed or amplified for causal intervention. We extend this to test whether identified PRM features causally influence verification accuracy.",
      "steering_experiments": [
        "Zero error-pattern features in discriminative PRM and measure accuracy drop on pattern-detectable errors vs. reasoning-requiring errors (expect selective degradation on pattern-detectable errors)",
